{"refs":["jobs"],"code":"from itertools import permutations

def solve(facts):
    jobs = facts['jobs']
    n = len(jobs)
    positions = {j['id']: i for i, j in enumerate(jobs)}
    required = [sum(1 << positions[p] for p in set(j['predecessors'])) for j in jobs]
    states = [{} for _ in range(1 << n)]
    states[0][0] = (0, (), ())
    for mask in range(1 << n):
        for time, (cost, order, starts) in states[mask].items():
            for i, job in enumerate(jobs):
                bit = 1 << i
                if mask & bit or required[i] & mask != required[i]:
                    continue
                start = max(time, job['release'])
                end = start + job['duration']
                candidate = (cost + job['weight'] * max(0, end - job['due']), order + (job['id'],), starts + (start,))
                target = states[mask | bit]
                old = target.get(end)
                if old is None or candidate[:2] < old[:2]:
                    target[end] = candidate
    if not states[-1]:
        raise ValueError('No feasible order')
    finish, result = min(states[-1].items(), key=lambda item: (item[1][0], item[0], item[1][1]))
    return {'order': list(result[1]), 'starts': list(result[2]), 'finish': finish, 'weighted_tardiness': result[0]}

def check(answer, facts):
    jobs = facts['jobs']
    best_key = None
    expected = None
    for sequence in permutations(jobs):
        completed = {}
        time = 0
        cost = 0
        order = []
        starts = []
        valid = True
        for job in sequence:
            if any(p not in completed for p in job['predecessors']):
                valid = False
                break
            start = max([time, job['release']] + [completed[p] for p in job['predecessors']])
            time = start + job['duration']
            completed[job['id']] = time
            cost += job['weight'] * max(0, time - job['due'])
            order.append(job['id'])
            starts.append(start)
        if not valid:
            continue
        key = (cost, time, tuple(order))
        if best_key is None or key < best_key:
            best_key = key
            expected = {'order': order, 'starts': starts, 'finish': time, 'weighted_tardiness': cost}
    return bool(expected is not None and isinstance(answer, dict) and answer == expected)
